import Foundation

/// Local-LLM description line for the Live Activity.
///
/// WHY: the Lock Screen description used to restate identity crumbs
/// ("elephant - Claude - https://github.com/… · +7 more"), which tells the user
/// nothing about what the agent is actually doing. This produces a one-sentence
/// natural-language summary from the same mirrored progress text, generated by
/// the on-device Token Saver model — no cloud call, no provider tokens spent.
///
/// The generation is deliberately **out of band**. `PetLiveActivityCopy.make`
/// is a pure synchronous mapper feeding a serialized delivery mailbox; awaiting
/// an 8-second model call there would stall every Live Activity update. Instead
/// the pet publishes immediately with the deterministic preview, a summary is
/// computed in the background, and the surface is republished when it lands.
/// If the model is unavailable, slow, subscription-gated, or returns junk, the
/// deterministic preview simply stays — the card is never blank or stale.
enum LiveActivitySummary {
    /// Hard ceiling for the generated line. `PetLiveActivityCopy.sanitize`
    /// clamps the preview to 80 characters anyway; asking for a little more and
    /// letting the sanitizer trim beats asking for less and getting a fragment.
    static let maximumCharacters = 110

    /// Minimum gap between model calls for the same card. An active run emits
    /// progress continuously; without this the sidecar would be asked to
    /// summarize on every tool line.
    static let minimumRefreshInterval: TimeInterval = 20

    // MARK: - Source

    /// What the model is asked to summarize, plus the fingerprint that decides
    /// when it is worth asking again.
    struct Source: Equatable, Sendable {
        /// Cache identity — the card this summary belongs to.
        let key: String
        /// Redacted progress text handed to the model.
        let text: String
        /// Changes only when the meaning changes, so cosmetic churn (elapsed
        /// timers ticking) does not trigger a regeneration.
        let fingerprint: String
    }

    /// Builds the summary source from the pet surface, or nil when there is
    /// nothing worth summarizing (the deterministic preview is already the
    /// whole truth).
    static func source(for input: PetLiveActivityCopy.Input) -> Source? {
        if let row = input.active.first, input.active.count == 1 {
            let parts = [row.lastUpdatePreview, row.detail].compactMap { $0 }
            guard !parts.isEmpty else { return nil }
            let text = parts.joined(separator: "\n")
            return Source(
                key: "active:\(row.threadID.value.uuidString)",
                text: text,
                fingerprint: fingerprint(text)
            )
        }
        if input.active.count > 1 {
            let lines = input.active.compactMap { $0.lastUpdatePreview ?? $0.detail }
            guard !lines.isEmpty else { return nil }
            let text = lines.prefix(6).joined(separator: "\n")
            return Source(
                key: "active-multi:\(input.active.count)",
                text: text,
                fingerprint: fingerprint(text)
            )
        }
        let finished = input.completed
        guard !finished.isEmpty else { return nil }
        let lines = finished.prefix(6).map { item in
            [item.title, item.detail].compactMap { $0 }.joined(separator: " — ")
        }
        let text = lines.joined(separator: "\n")
        return Source(
            key: "terminal:\(finished.count)",
            text: text,
            fingerprint: fingerprint(text)
        )
    }

    /// Cheap, stable content hash. Not security-sensitive — it only has to
    /// change when the text changes.
    static func fingerprint(_ text: String) -> String {
        var hash: UInt64 = 0xcbf2_9ce4_8422_2325
        for byte in text.utf8 {
            hash ^= UInt64(byte)
            hash = hash &* 0x0000_0100_0000_01B3
        }
        return String(hash, radix: 16)
    }

    // MARK: - Prompt

    /// Envelope for the `.sr1Humanize` distill mode — the only public mode that
    /// emits free natural language (the others emit compressed S/C/D/R/O/N/P
    /// lines, which would be unreadable on a Lock Screen).
    static func prompt(source: Source, targetLanguage: String) -> String {
        """
        TARGET_LANGUAGE: \(targetLanguage)
        USER_FACING_RULES:
        Write exactly one short sentence, at most \(maximumCharacters) characters, saying what the coding agent is doing right now.
        Use plain language. No markdown, no bullet points, no quotes, no prefixes, no labels.
        Only use facts present in SR1_RESPONSE. Never invent a file, command, or result.

        SR1_RESPONSE:
        \(source.text)
        """
    }

    // MARK: - Output guard

    // PERF: sanitized runs on every accepted model caption before Lock Screen
    // publish and recompiled whitespace + dialect-prefix patterns each call.
    private static let multiWhitespaceRegex = try! NSRegularExpression(pattern: #"\s+"#)
    private static let compressedDialectPrefixRegex = try! NSRegularExpression(
        pattern: #"^[SCDRONP]\s"#
    )

    private static func replaceAll(
        _ regex: NSRegularExpression,
        in text: String,
        with template: String
    ) -> String {
        let range = NSRange(location: 0, length: (text as NSString).length)
        return regex.stringByReplacingMatches(
            in: text,
            options: [],
            range: range,
            withTemplate: template
        )
    }

    /// Accepts a model line only when it is actually a usable sentence.
    ///
    /// The sidecar can hand back the verbatim input (its store-before-loss
    /// fallback), a compressed-dialect line, or an echo of the instructions. Any
    /// of those on the Lock Screen is worse than the deterministic preview, so
    /// this fails closed to nil.
    static func sanitized(_ raw: String?, source: Source) -> String? {
        guard let raw else { return nil }
        var line = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !line.isEmpty else { return nil }

        // Collapse to a single line — a Lock Screen row is two lines of caption.
        line = line
            .split(whereSeparator: \.isNewline)
            .map { $0.trimmingCharacters(in: .whitespaces) }
            .filter { !$0.isEmpty }
            .joined(separator: " ")
        line = replaceAll(multiWhitespaceRegex, in: line, with: " ")
        guard !line.isEmpty else { return nil }

        // Verbatim passthrough means the model never ran (or was bypassed).
        if line == source.text.trimmingCharacters(in: .whitespacesAndNewlines) { return nil }

        // Compressed-dialect output and leaked scaffolding are not prose.
        let lowered = line.lowercased()
        for marker in ["sr1_response", "target_language", "user_facing_rules", "<think>", "output:", "dict:"] {
            if lowered.contains(marker) { return nil }
        }
        let lineRange = NSRange(location: 0, length: (line as NSString).length)
        if compressedDialectPrefixRegex.firstMatch(in: line, options: [], range: lineRange) != nil {
            return nil
        }

        // Strip wrapping quotes the model sometimes adds despite the rules.
        if line.count > 1, line.hasPrefix("\""), line.hasSuffix("\"") {
            line = String(line.dropFirst().dropLast())
        }
        line = line.trimmingCharacters(in: .whitespacesAndNewlines)
        guard line.count >= 8 else { return nil }

        if line.count > maximumCharacters {
            line = String(line.prefix(maximumCharacters - 1)) + "…"
        }
        // Redaction + final length cap happen again in PetLiveActivityCopy.
        return PetAttentionRedactor.safeContextLabel(line)
    }
}

/// Thread-safe cache of generated summaries, keyed by card identity.
///
/// Reads happen on the main actor while the pet publishes; writes happen from a
/// background generation task. A lock keeps that honest without forcing the
/// publish path to await.
final class LiveActivitySummaryStore: @unchecked Sendable {
    private struct Entry {
        let text: String
        let fingerprint: String
        let generatedAt: Date
    }

    private let lock = NSLock()
    private var entries: [String: Entry] = [:]
    /// Fingerprints already in flight or already attempted, so a source that
    /// the model declines is not retried on every single publish.
    private var attempts: [String: (fingerprint: String, at: Date)] = [:]

    /// Cached summary for this exact source, or nil when the source changed.
    func summary(for source: LiveActivitySummary.Source) -> String? {
        lock.withLock {
            guard let entry = entries[source.key],
                  entry.fingerprint == source.fingerprint else { return nil }
            return entry.text
        }
    }

    /// True when it is worth asking the model again: the content changed and we
    /// are outside the debounce window.
    func shouldGenerate(
        for source: LiveActivitySummary.Source,
        now: Date = Date(),
        minimumInterval: TimeInterval = LiveActivitySummary.minimumRefreshInterval
    ) -> Bool {
        lock.withLock {
            // Already summarized this exact content.
            if let entry = entries[source.key], entry.fingerprint == source.fingerprint {
                return false
            }
            // Rate limit per card, regardless of how fast the content churns.
            // A failed attempt is recorded too, so a source the model declines
            // is not retried on every publish.
            if let attempt = attempts[source.key],
               now.timeIntervalSince(attempt.at) < minimumInterval {
                return false
            }
            attempts[source.key] = (fingerprint: source.fingerprint, at: now)
            return true
        }
    }

    func store(_ text: String, for source: LiveActivitySummary.Source, now: Date = Date()) {
        lock.withLock {
            entries[source.key] = Entry(
                text: text,
                fingerprint: source.fingerprint,
                generatedAt: now
            )
        }
    }

    /// Drops everything — used when the surface goes empty so a stale sentence
    /// cannot reappear on the next unrelated run.
    func reset() {
        lock.withLock {
            entries.removeAll()
            attempts.removeAll()
        }
    }
}
